<include file="Public:header"/><form id="myform" method="post" action="" enctype="multipart/form-data">    <input type="hidden" name="type_id" value="{pigcms{$_GET.type_id}"/>    <table cellpadding="0" cellspacing="0" class="frame_form" width="100%">        <tr>            <th width="80">商家类型名称</th>            <td><input type="text" class="input fl" name="type_name" value="{pigcms{$info['type_name']}" id="type_name"  size="25" placeholder="" validate="maxlength:20,required:true" tips=""/></td>        </tr>        <tr>            <th width="80">状态</th>            <td>                <span class="cb-enable"><label class="cb-enable <if condition="$info['type_status'] eq 0">selected</if>"><span>开启</span><input name="type_status" type="radio" value="0" <if condition="$info['type_status'] eq 0">checked="checked"</if> /></label></span>                <span class="cb-disable"><label class="cb-disable <if condition="$info['type_status'] eq 1">selected</if>"><span>禁止</span><input name="type_status" type="radio" value="1" <if condition="$info['type_status'] eq 1">checked="checked"</if> /></label></span>            </td>        </tr>        <tr>            <th width="80">享受价格</th>            <td>                <span class="cb-enable"><label class="cb-enable <if condition="$info['is_vip'] eq 1">selected</if>"><span>VIP批发价</span><input name="is_vip" type="radio" value="1" <if condition="$info['is_vip'] eq 1">checked="checked"</if> /></label></span>                <span class="cb-disable"><label class="cb-disable <if condition="$info['is_vip'] eq 0">selected</if>"><span>普通批发价</span><input name="is_vip" type="radio" value="0" <if condition="$info['is_vip'] eq 0">checked="checked"</if> /></label></span>            </td>        </tr>        <tr>            <th width="80">排序</th>            <td><input type="text" class="input fl" name="sort" value="{pigcms{$info['sort']}" size="10" placeholder="排序" validate="maxlength:6,required:true,number:true" tips="默认添加时间排序！手动排序数值越大，排序越前。"/></td>        </tr>    </table>    <div class="btn hidden">        <input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />        <input type="reset" value="取消" class="button" />    </div></form><include file="Public:footer"/>